<div class="wrap">
  <header>
    <h1>My Bookmarks</h1>
    <p>A calm place to save links and find them again.</p>
  </header>

  <div class="save-bar">
    <input id="urlInput" type="text" placeholder="Paste a link to save…" autocomplete="off" />
    <button class="btn" id="saveBtn">Save</button>
  </div>

  <div class="list" id="list"></div>
</div>

<!-- Review / adjust modal -->
<div class="overlay" id="overlay">
  <div class="modal">
    <h2>Save this link</h2>
    <p class="hint" id="modalHint">We filled in the details from the page. Adjust anything you like.</p>
    <div class="field">
      <label>Title</label>
      <input id="fTitle" type="text" />
      <div class="auto" id="titleAuto">✓ filled in for you</div>
    </div>
    <div class="field">
      <label>Description</label>
      <textarea id="fDesc"></textarea>
      <div class="auto" id="descAuto">✓ filled in for you</div>
    </div>
    <div class="field">
      <label>Your note (optional)</label>
      <textarea id="fNote" placeholder="Why is this worth keeping?"></textarea>
    </div>
    <div class="field">
      <label>Labels (comma separated)</label>
      <input id="fTags" type="text" placeholder="e.g. reading, work" />
    </div>
    <div class="actions">
      <button class="btn secondary" id="cancelBtn">Cancel</button>
      <button class="btn" id="confirmBtn">Save to my list</button>
    </div>
  </div>
</div>

<script>
  // --- simulated "fetch page details" (prototype only) ---
  const SAMPLES = {
    "developer.mozilla.org": { title: "Array.prototype.reduce() - JavaScript | MDN", desc: "The reduce() method executes a reducer function on each element of the array, resulting in a single output value." },
    "www.nytimes.com": { title: "The Quiet Power of Reading Slowly - The New York Times", desc: "Why unhurried reading may be the antidote to information overload." },
    "en.wikipedia.org": { title: "Spaced repetition - Wikipedia", desc: "A learning technique that incorporates increasing intervals of time between reviews of previously learned material." },
    "github.com": { title: "sindresorhus/awesome: Curated list of awesome lists", desc: "A community-driven collection of awesome resources on many topics." },
    "www.smashingmagazine.com": { title: "Designing Calm Interfaces - Smashing Magazine", desc: "Principles for building software that respects a user's attention." }
  };
  function domainOf(url){ try { return new URL(url.match(/^https?:\/\//)? url : "https://"+url).hostname; } catch(e){ return ""; } }
  function titleCaseFromDomain(d){ const base = d.replace(/^www\./,"").split(".")[0]; return base ? base.charAt(0).toUpperCase()+base.slice(1)+" — saved page" : "Untitled page"; }
  function fetchDetails(url){
    const d = domainOf(url);
    if (SAMPLES[d]) return { ...SAMPLES[d], auto:true };
    return { title: titleCaseFromDomain(d), desc: "", auto: d ? true : false };
  }

  // --- state ---
  let bookmarks = JSON.parse(localStorage.getItem("bm_proto")||"[]");
  let pendingUrl = "";
  function save(){ localStorage.setItem("bm_proto", JSON.stringify(bookmarks)); }

  const listEl = document.getElementById("list");
  function render(){
    if(!bookmarks.length){
      listEl.innerHTML = '<div class="empty"><div class="big">Nothing saved yet.</div><div>Paste a link above to keep your first one.</div></div>';
      return;
    }
    listEl.innerHTML = bookmarks.map(b => `
      <div class="item">
        <p class="title">${esc(b.title)}</p>
        <p class="url">${esc(b.url)}</p>
        ${b.desc? `<p class="desc">${esc(b.desc)}</p>`:""}
        ${b.note? `<p class="note">${esc(b.note)}</p>`:""}
        ${b.tags && b.tags.length? `<div class="chips">${b.tags.map(t=>`<span class="chip">${esc(t)}</span>`).join("")}</div>`:""}
      </div>`).join("");
  }
  function esc(s){ return (s||"").replace(/[&<>"]/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c])); }

  // --- save flow ---
  const overlay = document.getElementById("overlay");
  const urlInput = document.getElementById("urlInput");
  document.getElementById("saveBtn").onclick = startSave;
  urlInput.addEventListener("keydown", e=>{ if(e.key==="Enter") startSave(); });

  function startSave(){
    const url = urlInput.value.trim();
    if(!url) return;
    pendingUrl = url;
    document.getElementById("fTitle").value = "…";
    document.getElementById("fDesc").value = "";
    document.getElementById("fNote").value = "";
    document.getElementById("fTags").value = "";
    document.getElementById("modalHint").textContent = "Reading the page…";
    document.getElementById("titleAuto").style.display="none";
    document.getElementById("descAuto").style.display="none";
    overlay.classList.add("open");
    // simulate fetch latency
    setTimeout(()=>{
      const d = fetchDetails(url);
      document.getElementById("fTitle").value = d.title;
      document.getElementById("fDesc").value = d.desc;
      document.getElementById("modalHint").textContent = "We filled in the details from the page. Adjust anything you like.";
      document.getElementById("titleAuto").style.display = d.auto? "block":"none";
      document.getElementById("descAuto").style.display = d.desc? "block":"none";
    }, 650);
  }

  document.getElementById("cancelBtn").onclick = ()=> overlay.classList.remove("open");
  document.getElementById("confirmBtn").onclick = ()=>{
    const tags = document.getElementById("fTags").value.split(",").map(s=>s.trim()).filter(Boolean);
    bookmarks.unshift({
      url: pendingUrl,
      title: document.getElementById("fTitle").value.trim() || pendingUrl,
      desc: document.getElementById("fDesc").value.trim(),
      note: document.getElementById("fNote").value.trim(),
      tags: tags
    });
    save(); render();
    overlay.classList.remove("open");
    urlInput.value = "";
  };

  render();
  document.body.setAttribute("data-harness-ready","true");
</script>
</body>
</html>
